python - <<'PY'
from PIL import Image
import json,numpy as np
s=json.load(open('/app/runs/spec.json')); target=np.array(Image.open('/app/target.png').convert('RGB')).astype(float)/255
pal=np.array([w['rgb'] for w in s['static']['wells']['wells']])
def lab(rgb):
 c=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4);xyz=c@np.array([[.4124564,.2126729,.0193339],[.3575761,.7151522,.1191920],[.1804375,.0721750,.9503041]]);xyz/=np.array([.95047,1,1.08883]);f=np.where(xyz>(6/29)**3,xyz**(1/3),xyz/(3*(6/29)**2)+4/29);return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
p=lab(pal);t=lab(target); labmap=np.linalg.norm(t[...,None,:]-p,axis=-1).argmin(-1)
mm=227.185/1024; lo=8/mm;hi=1016-lo; edges=np.linspace(lo,hi,26)
candidates=[]
for j in range(25):
 for i in range(25):
  v0,v1=map(int,edges[j:j+2]);u0,u1=map(int,edges[i:i+2]);crop=t[v0:v1,u0:u1];mean=crop.mean((0,1)); main=int(np.linalg.norm(p-mean,axis=1).argmin()); cnt=np.bincount(labmap[v0:v1,u0:u1].ravel(),minlength=16);cnt[main]=0;sec=int(cnt.argmax());frac=cnt[sec]/cnt.sum(); delta=np.linalg.norm(p[sec]-p[main]);score=frac*delta
  if frac>.1 and delta>8:candidates.append((score,j,i,main,sec,frac,delta))
for x in sorted(candidates,reverse=True)[:40]: print(tuple(round(v,2) if isinstance(v,float) else v for v in x))
PY

